    const src = { item: __("set on the item"), reorder: __("from the reorder level"), safety: __("from safety stock"), default: __("default") }[r.src];
    const html = `<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:12px">
        <b style="font-size:15px">${esc(it.name)}</b><span class="text-muted">${esc(it.code)}${it.group ? ` · ${esc(it.group)}` : ""}</span>
        <span class="indicator-pill ${r.status === "low" ? "red" : r.status === "enough" ? "orange" : "green"}">${IV_ST[r.status][0]}</span></div>
      <table class="table table-sm"><thead><tr><th>${__("Warehouse")}</th><th class="text-right">${__("In stock")}</th><th class="text-right">${__("Reserved")}</th><th class="text-right">${__("On order")}</th><th class="text-right">${__("Value")}</th></tr></thead>
      <tbody>${st.map((s) => `<tr><td>${esc(s[0])}${(it.levels || {})[s[0]] ? ` <span class="text-muted small">(${__("reorder at")} ${qfmt(it.levels[s[0]])})</span>` : ""}</td><td class="text-right"><b>${qfmt(s[1])}</b> ${esc(it.uom)}</td><td class="text-right">${qfmt(s[2])}</td><td class="text-right">${qfmt(s[3])}</td><td class="text-right">${vnum(s[4])}</td></tr>`).join("")}</tbody>
      <tfoot><tr><th>${__("Total")}</th><th class="text-right">${qfmt(r.qty)} ${esc(it.uom)}</th><th></th><th></th><th class="text-right">${vnum(r.val)}</th></tr></tfoot></table>
      <div class="text-muted small">${__("Low below {0} {1}, Plenty above {2} {1}, Enough in between ({3}).", [qfmt(r.lo), esc(it.uom), qfmt(r.hi), src])} ${r.src === "item" || !d.has_levels ? "" : __("Set \"Low Stock Below\" and \"Plenty Stock Above\" on the item to change these.")}</div>`;
    const dlg = new frappe.ui.Dialog({ title: __("Stock by warehouse"), size: "large", fields: [{ fieldname: "b", fieldtype: "HTML" }],
      primary_action_label: __("Open item"), primary_action() { dlg.hide(); goForm("Item", it.code); },
      secondary_action_label: __("Stock ledger"), secondary_action() { dlg.hide(); frappe.route_options = { item_code: it.code }; frappe.set_route("query-report", "Stock Ledger"); } });
    dlg.fields_dict.b.$wrapper.html(html);
    dlg.show();
  }


  /* ---------------- actions ---------------- */
  on(ROOT, "click", (e) => {
    const act = e.target.closest("[data-act]");
    if (!e.target.closest(".fo-float-menu") && !(act && act.dataset.act === "iv-se")) closeMenus();
    if (!act) return;
    switch (act.dataset.act) {
      case "iv-retry": IV.err = null; renderInv(); loadInv(); break;
      case "iv-more": IV.n += 48; renderInv(); break;
      case "iv-add": frappe.new_doc("Item", { is_stock_item: 1 }); break;
      case "iv-se": { e.stopPropagation(); const co = IV.co ? { company: IV.co } : {};
        openMenu(act, [{ label: __("New stock entry"), icon: "plus", run: () => frappe.new_doc("Stock Entry", Object.assign({}, co)) },
          { label: __("Material receipt"), icon: "package", run: () => frappe.new_doc("Stock Entry", Object.assign({ stock_entry_type: "Material Receipt" }, co)) },
          { label: __("Material transfer"), icon: "truck", run: () => frappe.new_doc("Stock Entry", Object.assign({ stock_entry_type: "Material Transfer" }, co)) },
          { label: __("Material issue"), icon: "hardhat", run: () => frappe.new_doc("Stock Entry", Object.assign({ stock_entry_type: "Material Issue" }, co)) }, "-",
          { label: __("All stock entries"), icon: "list", run: () => goList("Stock Entry", Object.assign({}, co)) }]); break; }
    }
  });
  on(document, "click", (e) => { if (!e.composedPath().includes(HOST)) closeMenus(); });
  on(document, "keydown", (e) => { if (e.key === "Escape") closeMenus(); });
  // ---- full page width: remove the workspace max-width while this page is open, put it back on leave ----
  const WID = { saved: [] };
  const onInvPage = () => /\/solar-inventory\/?$/i.test(location.pathname);
  const unwiden = () => { WID.saved.forEach((p) => (p[0].style.maxWidth = p[1])); WID.saved = []; };
  const widen = () => {
    unwiden();
    if (!S.alive || !onInvPage() || !HOST.isConnected) return;
    let el = HOST;
    while (el && el !== document.body && el !== document.documentElement) {
      const mw = getComputedStyle(el).maxWidth;
      if (mw && mw !== "none") { WID.saved.push([el, el.style.maxWidth]); el.style.maxWidth = "none"; }
      el = el.parentElement;
    }
  };
  // coming back to this page (e.g. after saving a Stock Entry) refreshes the numbers
  const onRoute = () => { if (!onInvPage()) unwiden(); setTimeout(() => { widen(); if (S.alive && HOST.isConnected && HOST.offsetParent) loadInv(); }, 150); };
  if (frappe.router && frappe.router.on) frappe.router.on("change", onRoute);
  const destroy = () => {
    S.alive = false;
    unwiden();
    S.listeners.forEach(([el, ev, fn, opt]) => el.removeEventListener(ev, fn, opt));
    if (frappe.router && frappe.router.off) frappe.router.off("change", onRoute);
  };
  window.__solarInv = { destroy };
  widen(); setTimeout(widen, 300);
  showInv();
})();

style:
:host {display: block; container-type: inline-size; container-name: fo;}
* {box-sizing: border-box;}
[hidden] {display: none !important;}
.fo {--navy: #0F1E46; --text: #1F2A44; --muted: #5B6785; --line: #E8ECF4; --soft: #F6F8FC;
  --blue: #2563EB; --blue-50: #EAF1FF; --orange: #F97316; --orange-50: #FFF1E6;
  --purple: #7C3AED; --purple-50: #F2EDFF; --red: #E11D48; --red-50: #FFECEF; --sky: #2F6FEB; --sky-50: #E9F1FF;
  --green: #059669; --green-50: #E3F8EE;
  font-family: "Inter", "InterVariable", var(--font-stack, system-ui), -apple-system, "Segoe UI", sans-serif;
  color: var(--text); font-size: 14px; line-height: 1.4; -webkit-font-smoothing: antialiased;
  background: #FBFCFE; border: 1px solid var(--line); border-radius: 18px; padding: 26px 26px 28px;
  display: flex; flex-direction: column; gap: 22px; position: relative;}
button {font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer;}
a {color: inherit; text-decoration: none; cursor: pointer;}
svg.i {width: 18px; height: 18px; flex: none; stroke: currentColor; fill: none; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round;}
svg.i.sm {width: 15px; height: 15px;}
svg.i.lg {width: 30px; height: 30px; stroke-width: 1.8;}
.fo-pill {display: inline-flex; align-items: center; gap: 10px; height: 42px; padding: 0 14px; background: #fff; border: 1px solid var(--line); border-radius: 12px; box-shadow: 0 1px 2px rgba(15,30,70,.04); color: var(--navy); font-weight: 600; font-size: 14px; cursor: pointer;}
.fo-pill:hover {border-color: #CFD8EA;}
.fo-pill-ico {display: flex; color: var(--navy);}
.fo-menu {position: absolute; z-index: 60; background: #fff; border: 1px solid var(--line); border-radius: 12px; box-shadow: 0 14px 36px rgba(15,30,70,.14); padding: 6px; min-width: 210px;}
.fo-menu a {display: flex; align-items: center; gap: 10px; padding: 9px 12px; border-radius: 8px; color: var(--text); font-size: 13.5px; white-space: nowrap;}
.fo-menu a:hover, .fo-menu a.on {background: var(--blue-50); color: var(--blue);}
.fo-menu hr {border: 0; border-top: 1px solid var(--line); margin: 4px 0;}
.fo-card {background: #fff; border: 1px solid var(--line); border-radius: 16px; padding: 20px 14px 14px; box-shadow: 0 1px 2px rgba(15,30,70,.03), 0 6px 18px rgba(15,30,70,.035);}
.fo-skel {background: linear-gradient(90deg, #EEF2F8 25%, #F7F9FC 50%, #EEF2F8 75%); background-size: 200% 100%; animation: fo-sh 1.2s infinite linear; border-radius: 8px;}
@keyframes fo-sh{ to { background-position: -200% 0; } }
.fo-btn {display: inline-flex; align-items: center; gap: 6px; background: var(--blue); color: #fff; border-radius: 10px; padding: 8px 14px; font-weight: 600; font-size: 13px;}
.fo-btn.ghost {background: #fff; color: var(--blue); border: 1px solid #CFDCF7;}
.fo-err {display: flex; align-items: center; gap: 10px; color: #B42318; background: #FEF3F2; border: 1px solid #FEE4E2; padding: 10px 14px; border-radius: 12px; font-size: 13px; grid-column: 1 / -1;}
.fo-err a {margin-left: auto; font-weight: 700; text-decoration: underline;}
.fo-float-menu {min-width: 220px;}
@container fo (max-width: 820px) {
  .fo {padding: 16px; border-radius: 14px; gap: 16px;}
}
.fo-view {display: flex; flex-direction: column; gap: 22px; min-width: 0;}
.fo-search {cursor: text; min-width: 260px;}
.fo-search input {border: 0; outline: none; background: transparent; font: inherit; font-weight: 500; color: var(--navy); width: 100%;}
.fo-btn span {display: flex;}
.fo-btn svg.i {width: 15px; height: 15px;}
.pj-empty {color: var(--muted); font-size: 13.5px; padding: 14px 4px;}
.pj-empty a {color: var(--blue); font-weight: 600;}
.pj-tbl-wrap {overflow-x: auto; border: 1px solid #EEF1F7; border-radius: 12px;}
.pj-tbl {width: 100%; border-collapse: separate; border-spacing: 0; min-width: 640px;}
.pj-tbl th {background: #F5F7FB; text-align: left; font-weight: 500; color: #4A5676; font-size: 13px; padding: 11px 12px; white-space: nowrap;}
.pj-tbl td {padding: 11px 12px; border-top: 1px solid #EEF1F7; font-size: 13.5px; color: var(--text); white-space: nowrap;}
.pj-tbl th.r, .pj-tbl td.r {text-align: right;}
.pj-tbl tbody tr {cursor: pointer;}
.pj-tbl tbody tr:hover {background: #F8FAFF;}
@container fo (max-width: 900px) {
  .fo-search {min-width: 0; flex: 1;}
}
.fo-btn.lg {height: 44px; padding: 0 18px; font-size: 14.5px; border-radius: 11px;}
.fo-btn.ghost.lg {border-color: var(--line); color: var(--navy);}
.fo-btn.ghost.lg:hover {border-color: #CFD8EA; background: var(--soft);}
.pj-tbl tfoot td {background: #F8FAFD; border-top: 1px solid #E4E9F2; font-weight: 600; color: var(--navy); padding: 11px 12px; font-size: 13.5px; white-space: nowrap;}
.iv-head {display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;}
.iv-ttl {display: flex; align-items: center; gap: 16px; min-width: 0;}
.iv-ttl-ico {color: var(--navy); display: flex;}
.iv-ttl-ico svg.i.lg {width: 44px; height: 44px; stroke-width: 1.7;}
.iv-ttl h1 {margin: 0; font-size: 28px; font-weight: 700; color: var(--navy); letter-spacing: -.3px; line-height: 1.15;}
.iv-ttl p {margin: 3px 0 0; color: var(--muted); font-size: 15px;}
.iv-btns {display: flex; gap: 12px; flex-wrap: wrap;}
.iv-btns .fo-btn {height: 48px; padding: 0 20px; font-size: 15px; border-radius: 10px; gap: 10px;}
.iv-btns .fo-btn svg.i {width: 19px; height: 19px;}
.iv-btns .fo-btn.ghost {color: var(--navy); border-color: #D5DCE8;}
.iv-btns .fo-btn.ghost:hover {border-color: #B9C4D8; background: #FAFBFD;}
.iv-co {height: 48px; border-radius: 10px; border-color: #D5DCE8; max-width: 300px; min-width: 0; padding-right: 10px;}
.iv-co select {border: 0; outline: none; background: transparent; font: inherit; font-size: 15px; font-weight: 600; color: var(--navy); cursor: pointer; min-width: 0; max-width: 240px; text-overflow: ellipsis; padding-right: 6px;}
.iv-kpis {display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 18px;}
.iv-kpi {display: flex; align-items: center; gap: 18px; background: #fff; border: 1px solid var(--line); border-radius: 14px; padding: 20px 22px; cursor: pointer;
  box-shadow: 0 1px 2px rgba(15,30,70,.04); transition: box-shadow .15s, border-color .15s, transform .15s; min-width: 0;}
.iv-kpi:hover {transform: translateY(-1px); box-shadow: 0 2px 4px rgba(15,30,70,.05), 0 12px 28px rgba(15,30,70,.08);}
.iv-kpi.on {border-color: var(--kc); box-shadow: 0 0 0 1px var(--kc);}
.iv-kpi-ico {width: 68px; height: 68px; border-radius: 12px; display: grid; place-items: center; flex: none; background: var(--kb); color: var(--kc);}
.iv-kpi-ico svg.i.lg {width: 34px; height: 34px;}
.iv-kpi div {display: flex; flex-direction: column; gap: 4px; min-width: 0;}
.iv-kpi div span {color: #33405F; font-size: 16px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;}
.iv-kpi div b {color: var(--navy); font-size: 28px; font-weight: 700; line-height: 1.1;}
.k-blue {--kc: var(--blue); --kb: var(--blue-50);}
.k-red {--kc: #E11D48; --kb: #FFE4E8;}
.k-amber {--kc: #E8930C; --kb: #FFF3DC;}
.k-green {--kc: #0E9F6E; --kb: #DDF6EA;}
.iv-bar {display: flex; gap: 14px; align-items: center; flex-wrap: wrap;}
.iv-bar .fo-pill {height: 50px; border-radius: 10px; font-weight: 500;}
.iv-q {flex: 1.7 1 280px; min-width: 0;}
.iv-q input {font-size: 15px;}
.iv-sel {flex: 1 1 190px; min-width: 0; position: relative; padding-right: 10px;}
.iv-sel select {border: 0; outline: none; background: transparent; font: inherit; color: var(--navy); width: 100%; min-width: 0; cursor: pointer; font-size: 15px; text-overflow: ellipsis;}
.iv-mode {display: inline-flex; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; background: #fff; height: 50px; flex: none;}
.iv-mode button {width: 58px; display: grid; place-items: center; color: #46527A;}
.iv-mode button + button {border-left: 1px solid var(--line);}
.iv-mode button.on {background: var(--blue-50); color: var(--blue); box-shadow: inset 0 0 0 1.5px var(--blue); border-radius: 10px 0 0 10px;}
.iv-mode button + button.on {border-radius: 0 10px 10px 0;}
.iv-mode svg.i {width: 21px; height: 21px;}
.iv-grid {display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px;}
.iv-card {position: relative; background: #fff; border: 1px solid var(--line); border-radius: 14px; padding: 22px 22px 20px; display: flex; flex-direction: column; gap: 18px;
  cursor: pointer; min-width: 0; box-shadow: 0 1px 2px rgba(15,30,70,.04); transition: box-shadow .15s, transform .15s; outline: none;}
.iv-card:hover, .iv-card:focus-visible {transform: translateY(-1px); box-shadow: 0 2px 4px rgba(15,30,70,.05), 0 12px 28px rgba(15,30,70,.08);}
.iv-top {display: flex; gap: 18px; min-width: 0;}
.iv-img {width: 104px; height: 108px; flex: none; border-radius: 8px; overflow: hidden; background: #F3F5F9; display: grid; place-items: center;}
.iv-img img {width: 100%; height: 100%; object-fit: cover; display: block;}
.iv-ph {width: 100%; height: 100%; display: grid; place-items: center;}
.iv-ph svg.i.lg {width: 40px; height: 40px; stroke-width: 1.6;}
.iv-info {flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 8px; padding-top: 2px;}
.iv-info h3 {margin: 0; font-size: 16.5px; font-weight: 700; color: var(--navy); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding-right: 22px; line-height: 1.3;}
.iv-sku {display: flex; align-items: center; justify-content: space-between; gap: 8px; min-width: 0;}
.iv-sku > span:first-child {color: #5B6785; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0;}
.iv-st {display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px; border-radius: 8px; font-weight: 600; font-size: 13.5px; white-space: nowrap; flex: none;}
.iv-st i {width: 8px; height: 8px; border-radius: 50%; background: currentColor;}
.iv-st.s-low {background: #FFECEF; color: #DB1F48;}
.iv-st.s-enough {background: #FFF3DC; color: #C97A06;}
.iv-st.s-plenty {background: #E1F7EC; color: #0E8F5F;}
.iv-grp {align-self: flex-start; max-width: 100%; background: #F2F4F8; color: #46527A; font-size: 13px; padding: 5px 11px; border-radius: 7px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;}
.iv-dots {position: absolute; top: 16px; right: 12px; width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; color: var(--navy);}
.iv-dots:hover {background: #F1F4F9;}
.iv-tbl .iv-dots {position: static; display: inline-grid;}
.iv-foot {display: flex; align-items: center; gap: 18px; min-width: 0;}
.iv-qty {display: flex; align-items: baseline; gap: 8px; flex: none; padding-right: 18px; border-right: 1px solid var(--line);}
.iv-qty b {font-size: 28px; font-weight: 700; color: var(--navy); line-height: 1;}
.iv-qty span {font-size: 16px; color: #46527A;}
.iv-loc {display: flex; align-items: center; gap: 9px; color: #33405F; font-size: 14.5px; min-width: 0;}
.iv-loc span {white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0;}
.iv-loc small {color: var(--blue); font-weight: 600; font-size: 12.5px;}
.iv-more {display: flex; justify-content: center; align-items: center; gap: 14px; margin-top: 18px; color: var(--muted); font-size: 13px;}
.iv-lcard {padding: 6px 8px;}
.iv-tbl {min-width: 760px;}
.iv-tbl td {vertical-align: middle;}
.iv-tname {display: flex; align-items: center; gap: 12px; min-width: 0;}
.iv-tname b {color: var(--navy); font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 30cqw;}
.iv-timg {width: 40px; height: 40px; border-radius: 8px; overflow: hidden; flex: none; display: grid; place-items: center; background: #F3F5F9;}
.iv-timg img {width: 100%; height: 100%; object-fit: cover;}
.iv-timg .iv-ph svg.i.lg {width: 20px; height: 20px;}
.iv-tbl tr[data-ivi] {cursor: pointer;}
.iv-tbl tr[data-ivi]:hover td {background: #F8FAFE;}
.iv-mut {color: #5B6785;}
.iv-tbl .iv-mut small {color: var(--blue); font-weight: 600;}
@container fo (max-width: 1450px) {
  .iv-kpi {padding: 16px; gap: 14px;}
  .iv-kpi-ico {width: 56px; height: 56px;}
  .iv-kpi-ico svg.i.lg {width: 28px; height: 28px;}
  .iv-kpi div b {font-size: 25px;}
  .iv-kpi div span {font-size: 14.5px;}
  .iv-card {padding: 18px 16px 16px;}
  .iv-top {gap: 14px;}
  .iv-img {width: 88px; height: 92px;}
  .iv-info h3 {font-size: 15.5px;}
  .iv-sku > span:first-child {font-size: 13px;}
  .iv-st {padding: 5px 9px; font-size: 12.5px;}
  .iv-qty b {font-size: 24px;}
  .iv-qty span {font-size: 14.5px;}
  .iv-foot {gap: 14px;}
  .iv-qty {padding-right: 14px;}
  .iv-loc {font-size: 13.5px;}
}
@container fo (max-width: 1150px) {
  .iv-grid {grid-template-columns: repeat(2, minmax(0, 1fr));}
  .iv-kpi {padding: 14px; gap: 12px;}
  .iv-kpi-ico {width: 48px; height: 48px;}
  .iv-kpi-ico svg.i.lg {width: 24px; height: 24px;}
}
@container fo (max-width: 900px) {
  .iv-kpis {grid-template-columns: repeat(2, minmax(0, 1fr));}
}
@container fo (max-width: 700px) {
  .iv-grid, .iv-kpis {grid-template-columns: minmax(0, 1fr);}
  .iv-ttl h1 {font-size: 23px;}
  .iv-btns {width: 100%;}
  .iv-btns .fo-btn {flex: 1; justify-content: center;}
  .iv-co {flex: 1 1 100%; max-width: none;}
  .iv-co select {max-width: none; width: 100%;}
  .iv-sel, .iv-q {flex-basis: 100%;}
}
